import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Codex Cloud","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/codex-cloud.md","filePath":"zh/products/ai-coding/codex/codex-cloud.md","lastUpdated":1787046041000}'),d={name:"zh/products/ai-coding/codex/codex-cloud.md"};function l(i,t,h,s,n,c){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="codex-cloud" tabindex="-1">Codex Cloud <a class="header-anchor" href="#codex-cloud" aria-label="Permalink to &quot;Codex Cloud&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——在隔离的托管环境里跑编程任务，审 diff，再开 PR。Cloud 是 Codex 的一个入口，不是第二个产品。沙箱、审批、<code>AGENTS.md</code> 同样生效。</p><p>官方落地页：<a href="https://learn.chatgpt.com/codex/cloud" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/cloud</a>。文档：<a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a>。入口：<a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要</th><th>要求</th></tr></thead><tbody><tr><td>账号</td><td>含 Codex 的 ChatGPT 套餐。限额只看 <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">定价页</a></td></tr><tr><td>GitHub</td><td>能授权的 GitHub 账号，以及 Codex 可见的仓库</td></tr><tr><td>浏览器</td><td><a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a></td></tr><tr><td>可选 CLI</td><td>已装 <a href="./codex-cli.html">Codex CLI</a>，用来跑 <code>codex cloud</code> / <code>codex cloud exec</code></td></tr></tbody></table><p><strong>学习目标</strong>：建好一个 Cloud 环境；从网页或 CLI 派一次任务；会审摘要和 diff；知道什么时候该用 Cloud 而不是本机。</p><p><strong>非目标</strong>：本机沙箱（<a href="./codex-cli.html">CLI</a>）；IDE 第一次对话（<a href="./codex-ide.html">IDE</a>）；安全扫描（<a href="./codex-security.html">Security</a>）；套餐数字（<a href="./chatgpt-plus.html">套餐</a>）。</p><h2 id="cloud-是什么-不是什么" tabindex="-1">Cloud 是什么，不是什么 <a class="header-anchor" href="#cloud-是什么-不是什么" aria-label="Permalink to &quot;Cloud 是什么，不是什么&quot;">​</a></h2><p>Cloud 把 Codex 跑在 OpenAI 托管机器上，对着你为仓库配好的<strong>可复现环境</strong>干活。每个任务一份隔离环境，可以并行。做完再审。</p><p>它<strong>不是</strong>：</p><ul><li>第四个产品。托管 code review / QA 是 Cloud 上的工作流。</li><li>本机的替代品。对着当前文件的小改动，本地 CLI / IDE 更快。</li><li>ChatGPT Work 的 Cloud。Work Cloud 出 PPT / 调研；Codex Cloud 写代码、开 PR。</li></ul><p>桌面 Codex 仍在 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a> 里。入口写在 <a href="./codex-ai.html">产品线</a> 和 <a href="./chatgpt-work.html#桌面上-work-和-codex-怎么选">Work 与 Codex 对照</a>，这里不再重复一整页。</p><h2 id="什么时候用-cloud" tabindex="-1">什么时候用 Cloud <a class="header-anchor" href="#什么时候用-cloud" aria-label="Permalink to &quot;什么时候用 Cloud&quot;">​</a></h2><p>官方 “use Cloud when…”：</p><table tabindex="0"><thead><tr><th>场景</th><th>为什么用 Cloud</th></tr></thead><tbody><tr><td>任务要在后台跑</td><td>不占本机</td></tr><tr><td>要并行试几次</td><td><code>--attempts</code> / 多开会话，再挑</td></tr><tr><td>活从 <strong>GitHub / Linear / Slack</strong> 来</td><td>官方集成直接派进 Cloud</td></tr><tr><td>人不在开发机旁</td><td>网页或 <code>codex cloud exec</code></td></tr></tbody></table><p>本机文件、对着当前进程的调试、已经打开的文件上 30 秒改动，留在本地（<a href="./codex-ide.html">IDE</a>）。</p><h2 id="前-15-分钟" tabindex="-1">前 15 分钟 <a class="header-anchor" href="#前-15-分钟" aria-label="Permalink to &quot;前 15 分钟&quot;">​</a></h2><h3 id="_1-打开-codex-并登录" tabindex="-1">1. 打开 Codex 并登录 <a class="header-anchor" href="#_1-打开-codex-并登录" aria-label="Permalink to &quot;1. 打开 Codex 并登录&quot;">​</a></h3><p>打开 <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>，用和 CLI 同一套 ChatGPT 账号登录。</p><h3 id="_2-连接-github" tabindex="-1">2. 连接 GitHub <a class="header-anchor" href="#_2-连接-github" aria-label="Permalink to &quot;2. 连接 GitHub&quot;">​</a></h3><p>按提示授权。只开 Codex 该看见的仓库。</p><h3 id="_3-创建环境" tabindex="-1">3. 创建环境 <a class="header-anchor" href="#_3-创建环境" aria-label="Permalink to &quot;3. 创建环境&quot;">​</a></h3><p>打开 <a href="https://chatgpt.com/codex/settings/environments" target="_blank" rel="noreferrer">environment settings</a>，为仓库建环境。配好依赖、工具、环境变量和密钥。</p><p>细节：<a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a>。联网：<a href="https://learn.chatgpt.com/docs/cloud/internet-access" target="_blank" rel="noreferrer">Agent internet access</a>。</p><h3 id="_4-派第一个任务" tabindex="-1">4. 派第一个任务 <a class="header-anchor" href="#_4-派第一个任务" aria-label="Permalink to &quot;4. 派第一个任务&quot;">​</a></h3><p>回到 <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>，选环境，写<strong>结果</strong>，不要写感觉：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a failing test for the date parser in packages/core, then make it pass.</span></span>
<span class="line"><span>Do not touch packages/legacy. Open a draft PR when tests are green.</span></span></code></pre></div><p>可以盯日志，也可以让它后台跑。</p><h3 id="_5-先审再合" tabindex="-1">5. 先审再合 <a class="header-anchor" href="#_5-先审再合" aria-label="Permalink to &quot;5. 先审再合&quot;">​</a></h3><p>读摘要和 diff。要改就追问，准备好了再开 PR。不要因为「看起来对」就合。</p><h2 id="从-cli-派" tabindex="-1">从 CLI 派 <a class="header-anchor" href="#从-cli-派" aria-label="Permalink to &quot;从 CLI 派&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                            # 浏览环境（Ctrl+O 露出 ID）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the migration dry run&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attempts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 1–4 次</span></span></code></pre></div><p><code>--attempts</code> 给结果本身不确定的任务。挑最好的一次，不要平均。</p><h2 id="从-github、linear、slack-派活" tabindex="-1">从 GitHub、Linear、Slack 派活 <a class="header-anchor" href="#从-github、linear、slack-派活" aria-label="Permalink to &quot;从 GitHub、Linear、Slack 派活&quot;">​</a></h2><p>不用离开 PR、issue、频道或线程。</p><table tabindex="0"><thead><tr><th>从哪</th><th>官方页</th></tr></thead><tbody><tr><td>GitHub</td><td><a href="https://learn.chatgpt.com/docs/third-party/github" target="_blank" rel="noreferrer">Use Codex with GitHub</a></td></tr><tr><td>Linear</td><td><a href="https://learn.chatgpt.com/docs/third-party/linear" target="_blank" rel="noreferrer">Use Codex in Linear</a></td></tr><tr><td>Slack</td><td><a href="https://learn.chatgpt.com/docs/third-party/slack" target="_blank" rel="noreferrer">Use Codex in Slack</a></td></tr></tbody></table><p>IDE 也可以把长任务交给 Cloud，回到同一条会话审：<a href="https://learn.chatgpt.com/docs/cloud#delegate-from-the-ide-extension" target="_blank" rel="noreferrer">从 IDE 委派</a>。</p><h2 id="托管评审是-cloud-不是第四个产品" tabindex="-1">托管评审是 Cloud，不是第四个产品 <a class="header-anchor" href="#托管评审是-cloud-不是第四个产品" aria-label="Permalink to &quot;托管评审是 Cloud，不是第四个产品&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>做什么</th></tr></thead><tbody><tr><td>本机 <code>/review</code></td><td>相对 base 或未提交 diff；不改树</td></tr><tr><td>Cloud code review / QA</td><td>托管环境里评审 / QA。合格客户用 <strong>GPT-5.6 Sol</strong>，模型由 Cloud 选</td></tr><tr><td>Codex Security Review</td><td>PR + 仓库上下文 + 威胁模型。研究预览，见 <a href="./codex-security.html">Security</a></td></tr></tbody></table><p>本机 <code>/review</code> 是会话命令，不要和托管评审混名。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>结果</th><th>改做</th></tr></thead><tbody><tr><td>不配环境就派活</td><td>缺依赖、空 diff</td><td>先配环境</td></tr><tr><td>把 Cloud 当第二台笔记本</td><td>本机密钥和本地工具不在</td><td>密钥放进环境；本机活留本机</td></tr><tr><td>合第一个「看起来对」的 PR</td><td>测试没跑，或跑错树</td><td>读 diff，要测试输出</td></tr><tr><td>和 Work Cloud 搞混</td><td>得到 PPT 而不是 PR</td><td>进 <strong>Codex</strong>：<a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a></td></tr><tr><td>电脑睡着还指望 Remote 那种 Cloud</td><td>产品不同</td><td><a href="./codex-remote.html">Remote</a> 驱动<strong>已配对电脑</strong>；Cloud 不需要那台机器醒着</td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>前端 monorepo：三条 Cloud 会话用 <code>--attempts 3</code> 试同一次发飘的迁移。你继续在 <a href="./codex-ide.html">IDE</a> 改设计系统。赢的那次开 draft PR。只有评审主机仍是那台笔记本时，才用 <a href="./codex-remote.html">Remote</a> 在手机上看；否则直接用网页 Cloud。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>环境旋钮 → <a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a></li><li>联网策略 → <a href="https://learn.chatgpt.com/docs/cloud/internet-access" target="_blank" rel="noreferrer">Agent internet access</a></li><li>编辑器交接 → <a href="./codex-ide.html">IDE</a></li><li>手机批<strong>本机</strong>会话 → <a href="./codex-remote.html">Remote</a></li><li>自建 CI → <a href="./integration.html">项目集成</a></li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/cloud" target="_blank" rel="noreferrer">Codex cloud（落地页）</a></li><li><a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud（文档）</a></li><li><a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a></li><li><a href="https://learn.chatgpt.com/docs/cloud/internet-access" target="_blank" rel="noreferrer">Agent internet access</a></li><li><a href="https://learn.chatgpt.com/docs/third-party/github" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://learn.chatgpt.com/docs/third-party/linear" target="_blank" rel="noreferrer">Linear</a> · <a href="https://learn.chatgpt.com/docs/third-party/slack" target="_blank" rel="noreferrer">Slack</a></li><li><a href="https://learn.chatgpt.com/docs/code-review" target="_blank" rel="noreferrer">Code review</a></li><li><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a></li></ul>`,47)])])}const f=e(d,[["render",l]]);export{b as __pageData,f as default};
